package clipboard

import (
	"bytes"
	"encoding/binary"
	"image/png"
	"math"
	"slices"
)

// secretFormats are the clipboard formats that password managers set to ask
// history tools to skip a copy. See http://nspasteboard.org and the Windows
// clipboard docs.
var secretFormats = []string{
	"org.nspasteboard.ConcealedType",
	"org.nspasteboard.TransientType",
	"org.nspasteboard.AutoGeneratedType",
	"com.apple.is-sensitive",
	"ExcludeClipboardContentFromMonitorProcessing",
	"Clipboard Viewer Ignore",
	"x-kde-passwordManagerHint",
}

// HistoryFormat is the Windows format whose 32-bit value, when 0, keeps a
// copy out of clipboard histories.
const HistoryFormat = "CanIncludeInClipboardHistory"

// MarkerFormats are the formats to request beside the content, so a read
// that returns the content also returns the markers of the same copy.
func MarkerFormats() []string { return append(slices.Clone(secretFormats), HistoryFormat) }

// Marked reports whether a copy that offers formats was marked secret by its
// source. It needs no format's bytes.
func Marked(formats []string) bool {
	return slices.ContainsFunc(formats, func(f string) bool { return slices.Contains(secretFormats, f) })
}

// KeptOutOfHistory reports whether a HistoryFormat value keeps a copy out of
// history. 0 does. A value that cannot be read (shorter than 4 bytes) does
// too, as a busy clipboard does, rather than risk saving a password.
func KeptOutOfHistory(value []byte) bool {
	return len(value) < 4 || binary.LittleEndian.Uint32(value) == 0
}

// passwordApps copy passwords without a secret marker.
var passwordApps = []string{"com.apple.Passwords", "com.apple.keychainaccess"}

// PasswordApp reports whether the app with this bundle ID copies secrets
// without marking them.
func PasswordApp(bundleID string) bool { return slices.Contains(passwordApps, bundleID) }

// look is the change counter and whether a password app was in front, at
// one look.
type look struct {
	change             uint64
	passwordAppInFront bool
}

// noLook is before the first look: any first change counts as new.
var noLook = look{change: math.MaxUint64}

// next says whether a change seen now may come from a password app, and the
// look to keep for next time. The monitor looks only twice a second, so a
// copy made just before the user switched away shows up with another app in
// front; a password app in front at the look before counts too.
func (last look) next(change uint64, passwordAppNowInFront bool) (secret bool, next look) {
	secret = change != last.change && (last.passwordAppInFront || passwordAppNowInFront)
	return secret, look{change, passwordAppNowInFront}
}

// Looks remembers copies made in a password app, which marks nothing, so a
// copy stays secret after the user leaves the app. The zero value has not
// looked yet. It is not safe for concurrent use.
type Looks struct {
	started bool
	last    look
	// passwordCopy is the latest change made while a password app was in
	// front.
	passwordCopy uint64
}

// Look notes the change counter and whether a password app is in front
// now, and reports whether the copy at change is secret. Call it at every
// tick of the monitor, also while history is off, and before every read:
// whether a copy is secret depends on the look before.
func (l *Looks) Look(change uint64, passwordAppInFront bool) (secret bool) {
	if !l.started {
		l.started, l.last, l.passwordCopy = true, noLook, math.MaxUint64
	}
	newSecret, next := l.last.next(change, passwordAppInFront)
	if newSecret {
		l.passwordCopy = change
	}
	l.last = next
	return l.passwordCopy == change || passwordAppInFront
}

// Capture is what clipboard history keeps besides text: the user's opt-ins.
type Capture struct {
	Images, Files bool
}

// Offer is what the clipboard holds, as far as choosing needs to know.
type Offer struct {
	// Files are the local paths of copied files.
	Files []string
	Text  bool
	Image bool
}

// Choose picks what to keep from an offer, in the order apps expect: copied
// files first (Finder also offers their names as text), then text, then an
// image. Kinds the user did not opt into are skipped, not saved as text. It
// returns "" for nothing.
func (c Capture) Choose(o Offer) Kind {
	switch {
	case len(o.Files) > 0:
		if c.Files {
			return KindFiles
		}
		return ""
	case o.Text:
		return KindText
	case o.Image && c.Images:
		return KindImage
	}
	return ""
}

// PNGImage is a copied PNG image with its size from the header, or false
// when it is not a PNG or is too large to keep.
func PNGImage(data []byte) (Content, bool) {
	if len(data) > MaxImageBytes {
		return Content{}, false
	}
	config, err := png.DecodeConfig(bytes.NewReader(data))
	if err != nil || config.Width < 0 || config.Height < 0 {
		return Content{}, false
	}
	image := Image(data, uint32(config.Width), uint32(config.Height))
	return image, image.Fits()
}
